import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        int n = scanner.nextInt();
        double ratio = (double) x / y;
        double t = 1 + ratio;
        double minDifference = 1e-15;
        int bestNum = 0;
        int bestDen = 1;
        for (int i = 1; i <= n; i++) {
            double candidate = (double) ((int) (ratio * i)) / i;
            double diff = Math.abs(candidate - ratio);
            if (!(diff > t - minDifference && diff < t + minDifference)) {
                if (diff < minDifference) {
                    minDifference = diff;
                    bestNum = (int) (ratio * i);
                    bestDen = i;
                }
            }
            double candidate2 = (double) ((int) (ratio * i + 1)) / i;
            double diff2 = Math.abs(candidate2 - ratio);
            if (!(diff2 > t - minDifference && diff2 < t + minDifference)) {
                if (diff2 < minDifference) {
                    minDifference = diff2;
                    bestNum = (int) (ratio * i) + 1;
                    bestDen = i;
                }
            }
        }
        System.out.println(bestNum + "/" + bestDen);
        scanner.close();
    }
}
